import sys
from collections import defaultdict

def solve(n, b, p):
    graph = defaultdict(list)
    root = -1
    for i in range(n):
        if b[i] == i + 1:
            root = i + 1
        else:
            graph[b[i]].append(i + 1)

    pos = {v: i for i, v in enumerate(p)}
    weights = [0] * (n + 1)
    visited = [False] * (n + 1)

    def dfs(node, current_weight):
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                required_weight = 1
                if pos[neighbor] > pos[node]:
                    required_weight = max(required_weight, current_weight + 1)
                weights[neighbor] = required_weight
                dfs(neighbor, required_weight)

    dfs(root, 0)

    dist = [0] * (n + 1)
    def calculate_distances(node, current_dist):
        dist[node] = current_dist
        for neighbor in graph[node]:
            calculate_distances(neighbor, current_dist + weights[neighbor])

    calculate_distances(root, 0)

    for i in range(n - 1):
        if dist[p[i]] >= dist[p[i + 1]]:
            return -1

    return ' '.join(str(weights[i]) for i in range(1, n + 1))

input = sys.stdin.read().split()
index = 0
t = int(input[index])
index += 1
results = []
for _ in range(t):
    n = int(input[index])
    index += 1
    b = list(map(int, input[index:index + n]))
    index += n
    p = list(map(int, input[index:index + n]))
    index += n

    result = solve(n, b, p)
    results.append(result)

print('\n'.join(results))
